properties.query:
let windowSize = 1h;

// S24: C2 Jam/Takeover — 메시 네트워크 컨텍스트에서 UAVDatalinkConn_CL에 병기되는 SwarmId 필드
let S24 =
    UAVDatalinkConn_CL
    | where TimeGenerated > ago(windowSize)
    | where ConnEvent in ('jam','takeover_attempt')
    | extend Stage = 'S24', SwarmId = tostring(SwarmId)
    | where isnotempty(SwarmId)
    | project TimeGenerated, Stage, SwarmId;

// S108: Mesh Partition
let S108 =
    UAVSwarmComms_CL
    | where TimeGenerated > ago(windowSize)
    | where EventType == 'mesh_partition'
    | extend Stage = 'S108', SwarmId = tostring(SwarmId)
    | where isnotempty(SwarmId)
    | project TimeGenerated, Stage, SwarmId;

// S1: GNSS Spoofing — 군집 임무 컨텍스트에서 UAVTelemetry_CL에 병기되는 SwarmId 필드
let S1 =
    UAVTelemetry_CL
    | where TimeGenerated > ago(windowSize)
    | where MsgType == 'EKF_STATUS_REPORT' and PosHorizVariance > 5.0
    | extend Stage = 'S1', SwarmId = tostring(SwarmId)
    | where isnotempty(SwarmId)
    | project TimeGenerated, Stage, SwarmId;

// S103: Collision Course
let S103 =
    UAVSwarmComms_CL
    | where TimeGenerated > ago(windowSize)
    | where EventType == 'collision_course'
    | extend Stage = 'S103', SwarmId = tostring(SwarmId)
    | where isnotempty(SwarmId)
    | project TimeGenerated, Stage, SwarmId;

union S24, S108, S1, S103
| summarize StagesSeen = make_set(Stage), StageCount = dcount(Stage), FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated) by SwarmId
| where StageCount >= 3
| extend CampaignType = "C26_분단격파_C2재밍_메시파티션_고립스푸핑_충돌"
| extend StepSummary = strcat("Stages=", tostring(StagesSeen), " | First=", tostring(FirstSeen), " | Last=", tostring(LastSeen))
| extend Severity = "High"
| project FirstSeen, LastSeen, SwarmId, StagesSeen, StageCount, CampaignType, StepSummary, Severity
